export const blueprintCategories = categories.map(({ name, tip }) => ({ name, tip }));
export const blueprints: Blueprint[] = categories.flatMap(category => category.entries.map(([name, useWhen, outcome, tasks]) => ({
  id: name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/-$/, ""),
  category: category.name, name, useWhen, outcome, task_titles: tasks.split("|"),
})));

export function blueprintDescription(blueprint: Blueprint) {
  return `Use when: ${blueprint.useWhen}\n\nExpected outcome: ${blueprint.outcome}\n\nBefore starting: agree scope and success criteria. After creating tasks, assign owners and due dates, add dependencies where needed, and attach completion evidence.`;
}
